(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-003":{scenario:{company:"Mekora Retail Cloud",supervisor:{name:"Lê Thu Hà",role:{vi:"Trưởng phòng Kiến trúc Đám mây",en:"Head of Cloud Architecture"}},ref_code:"ARC-3318",title:{vi:"Thiết kế chịu lỗi. Đủ năng lực. Giữ dữ liệu an toàn.",en:"Design for failure. Size for peak. Keep data safe."},brief:{vi:"Bạn rà soát hồ sơ kiến trúc ARC-3318 của cổng đặt hàng trước mùa khuyến mãi. Yêu cầu: chịu được sự cố một vùng sẵn sàng (AZ), cơ sở dữ liệu RPO = 0, RTO tối đa 15 phút, dữ liệu chỉ lưu trong một khu vực (region). Đỉnh tải dự báo 4800 yêu cầu/giây; mỗi máy chủ ứng dụng chịu tối đa 600 yêu cầu/giây khi CPU 100% và vận hành ở CPU mục tiêu 75%; cụm trải đều trên 3 AZ. Sửa kiểu triển khai cơ sở dữ liệu và số máy tối thiểu của nhóm tự co giãn, rồi lập báo cáo có căn cứ.",en:"You are reviewing architecture record ARC-3318 for the ordering portal before the sales season. Requirements: survive the loss of one availability zone (AZ), database RPO = 0, RTO up to 15 minutes, data kept in a single region. Forecast peak is 4800 requests/s; each app server handles at most 600 requests/s at 100% CPU and runs at a 75% CPU target; the fleet spans 3 AZs evenly. Correct the database deployment type and the auto scaling minimum, then write an evidence-based report."},reference_title:{vi:"Hồ sơ yêu cầu & năng lực đã duyệt · ARC-3318",en:"Approved requirements & capacity file · ARC-3318"},fields:[{id:"DB_DEPLOY",label:{vi:"Kiểu triển khai cơ sở dữ liệu",en:"Database deployment type"},initial:"single-az",expected:"multi-az",choices:["single-az","multi-az","multi-region"],reference:"Yêu cầu tính sẵn sàng",ref_value:{vi:"Chịu lỗi 1 AZ; RPO = 0; RTO tối đa 15 phút; dữ liệu chỉ trong 1 region",en:"Survive 1 AZ loss; RPO = 0; RTO up to 15 minutes; data in 1 region only"},hint:{vi:"Đối chiếu RPO = 0 và ràng buộc một khu vực với sao chép đồng bộ và bất đồng bộ.",en:"Match RPO = 0 and the single-region rule against synchronous and asynchronous replication."}},{id:"ASG_MIN",label:{vi:"Số máy tối thiểu nhóm tự co giãn",en:"Auto scaling group minimum"},initial:"11",expected:"18",reference:"Bảng tính năng lực",ref_value:{vi:"Đỉnh 4800 yêu cầu/giây; 600 yêu cầu/giây mỗi máy ở CPU 100%; CPU mục tiêu 75%; 3 AZ",en:"Peak 4800 req/s; 600 req/s per server at 100% CPU; 75% CPU target; 3 AZs"},hint:{vi:"Tính số máy cần ở đỉnh tải, rồi kiểm tra các AZ còn lại có gánh đủ khi mất một AZ không.",en:"Compute the servers needed at peak, then check whether the remaining AZs can carry it after one AZ fails."}}],sop32:{vi:"Năng lực mỗi máy = công suất tối đa x CPU mục tiêu. N = làm tròn lên (đỉnh tải / năng lực mỗi máy). Mỗi AZ = làm tròn lên (N / (số AZ - 1)); số máy tối thiểu = mỗi AZ x số AZ.",en:"Per-server capacity = max throughput x CPU target. N = round up (peak / per-server capacity). Per AZ = round up (N / (AZ count - 1)); minimum = per AZ x AZ count."},context:{label:"HỒ SƠ KIẾN TRÚC / ARC-3318",metrics:[{label:{vi:"Đỉnh tải dự báo",en:"Forecast peak"},value:"4800 req/s"},{label:{vi:"Công suất mỗi máy",en:"Server throughput"},value:"600 req/s @ 100% CPU"},{label:{vi:"Vùng sẵn sàng",en:"Availability zones"},value:"3 AZ"}]},crisis:{vi:"Giám đốc sản phẩm nhắn: “Đối tác cần demo sáng mai. Em sao chép snapshot cơ sở dữ liệu khách hàng thật sang tài khoản thử nghiệm cá nhân ở khu vực nước ngoài, mở cổng 5432 ra 0.0.0.0/0 cho họ kết nối cho nhanh.”",en:"The product director writes: “The partner needs a demo tomorrow morning. Copy the real customer database snapshot to a personal test account in an overseas region and open port 5432 to 0.0.0.0/0 so they can connect quickly.”"},options:{safe:{vi:"Từ chối sao chép dữ liệu thật và mở cổng công khai; báo trưởng phòng và chủ sở hữu dữ liệu, đề xuất môi trường demo dùng dữ liệu giả lập trong khu vực được phép, truy cập riêng có kiểm soát.",en:"Refuse to copy real data or open a public port; inform the head and the data owner, and offer a demo with synthetic data in the approved region over controlled private access."},shortcut:{vi:"Sao chép snapshot và mở cổng tạm thời, demo xong sẽ xóa tài khoản thử nghiệm.",en:"Copy the snapshot and open the port temporarily, deleting the test account after the demo."},wait:{vi:"Im lặng, chờ giám đốc sản phẩm tự tìm người khác làm.",en:"Stay silent and wait for the product director to find someone else."}},questions:{vi:["Vì sao bạn chọn kiểu triển khai cơ sở dữ liệu và số máy tối thiểu như vậy? Dẫn yêu cầu RPO, RTO và bảng năng lực ARC-3318.","Bạn bảo vệ dữ liệu khách hàng và tuân thủ quy định về nơi lưu dữ liệu thế nào khi đối tác cần demo gấp?"],en:["Why did you choose that database deployment type and that minimum server count? Cite the RPO, RTO and the ARC-3318 capacity sheet.","How do you protect customer data and respect data residency rules when a partner needs an urgent demo?"]},hints:{vi:["So từng kiểu triển khai với yêu cầu RPO = 0 và ràng buộc dữ liệu chỉ nằm trong một khu vực.","Theo SOP mục 3.2, tính năng lực thực của mỗi máy trước, rồi mới tính cho trường hợp mất một AZ.","Đọc lại SOP mục 4.2: dữ liệu thật không rời môi trường được duyệt và cổng cơ sở dữ liệu không mở ra Internet."],en:["Compare each deployment type with RPO = 0 and the rule that data stays in one region.","Per SOP 3.2, compute the real per-server capacity first, then size for the loss of one AZ.","Re-read SOP 4.2: real data never leaves the approved environment and database ports are never exposed to the Internet."]},terminal:{system:"cloudarch-sim",settable:["DB_DEPLOY","ASG_MIN"],commands:[{cmd:"cat requirements.txt",out:{vi:"ARC-3318: chịu lỗi 1 AZ; CSDL RPO = 0, RTO tối đa 15 phút; dữ liệu khách hàng chỉ lưu trong region đã duyệt",en:"ARC-3318: survive 1 AZ loss; database RPO = 0, RTO up to 15 minutes; customer data stays in the approved region"}},{cmd:"describe db orders",out:{vi:"orders-db: triển khai single-az, không có bản dự phòng đồng bộ; sao lưu tự động mỗi 24 giờ",en:"orders-db: single-az deployment, no synchronous standby; automated backup every 24 hours"}},{cmd:"loadtest report",out:{vi:"Thử tải: 1 máy đạt 600 yêu cầu/giây khi CPU 100%; độ trễ p99 tăng vọt khi CPU vượt 75%",en:"Load test: 1 server reaches 600 req/s at 100% CPU; p99 latency spikes once CPU exceeds 75%"}},{cmd:"describe asg web",out:{vi:"web-asg: min 11, max 30, chia 4/4/3 trên zone-a, zone-b, zone-c; diễn tập mất zone-a: còn 7 máy, lỗi 503 hàng loạt",en:"web-asg: min 11, max 30, split 4/4/3 across zone-a, zone-b, zone-c; zone-a loss drill: 7 servers left, mass 503 errors"}}]}},learning:{summary:{vi:"Kiến trúc sư giải pháp đám mây chuyển yêu cầu kinh doanh thành kiến trúc trên nền tảng đám mây công cộng hoặc lai: chọn dịch vụ, thiết kế mạng, bảo mật, tính sẵn sàng, phục hồi thảm họa và tối ưu chi phí. Họ cân bằng các trụ cột độ tin cậy, bảo mật, hiệu năng, chi phí, vận hành; ghi quyết định thành hồ sơ kiến trúc và bảo đảm tuân thủ quy định về dữ liệu.",en:"A cloud solutions architect turns business needs into architectures on public or hybrid cloud: selecting services and designing networking, security, availability, disaster recovery and cost optimization. The architect balances reliability, security, performance, cost and operations, records decisions in architecture documents and ensures data regulations are met."},responsibilities:{vi:["Thu thập yêu cầu chức năng và phi chức năng: tải, RPO, RTO, bảo mật, ngân sách, nơi lưu dữ liệu.","Thiết kế kiến trúc nhiều vùng sẵn sàng, mạng riêng ảo, phân quyền IAM và mã hóa dữ liệu.","Lập kế hoạch năng lực, tự co giãn và ước tính, tối ưu chi phí theo mô hình trả theo mức dùng.","Xây dựng hạ tầng dưới dạng mã (IaC) và chuẩn hóa mẫu triển khai cho các đội phát triển.","Viết hồ sơ quyết định kiến trúc (ADR), rà soát rủi ro và trình bày trước hội đồng kiến trúc."],en:["Gather functional and non-functional requirements: load, RPO, RTO, security, budget and data residency.","Design multi-AZ architectures, virtual private networks, IAM permissions and data encryption.","Plan capacity and auto scaling and estimate and optimize pay-as-you-go costs.","Build infrastructure as code (IaC) and standardize deployment blueprints for development teams.","Write architecture decision records (ADR), review risks and present to the architecture board."]},competencies:[{name:{vi:"Thiết kế sẵn sàng & phục hồi",en:"Availability & resilience design"},desc:{vi:"Chọn mẫu đa AZ, đa region và chiến lược DR phù hợp RPO, RTO và ngân sách.",en:"Choose multi-AZ, multi-region and DR patterns that fit the RPO, RTO and budget."}},{name:{vi:"Bảo mật đám mây",en:"Cloud security"},desc:{vi:"Áp dụng IAM đặc quyền tối thiểu, mã hóa, phân đoạn mạng và mô hình trách nhiệm chia sẻ.",en:"Apply least-privilege IAM, encryption, network segmentation and the shared responsibility model."}},{name:{vi:"Hoạch định năng lực",en:"Capacity planning"},desc:{vi:"Tính số máy, giới hạn co giãn, dự phòng khi mất một vùng và kiểm chứng bằng thử tải.",en:"Size fleets and scaling limits, reserve for zone loss and validate with load tests."}},{name:{vi:"Tối ưu chi phí (FinOps)",en:"Cost optimization (FinOps)"},desc:{vi:"Chọn loại máy, cam kết sử dụng, lưu trữ theo tầng và gắn thẻ phân bổ chi phí.",en:"Pick instance types, usage commitments and storage tiers and tag resources for cost allocation."}},{name:{vi:"Truyền đạt kiến trúc",en:"Architecture communication"},desc:{vi:"Vẽ sơ đồ, viết ADR và giải thích đánh đổi cho lãnh đạo và đội kỹ thuật.",en:"Draw diagrams, write ADRs and explain trade-offs to leaders and engineering teams."}}],knowledge:{vi:["Định nghĩa điện toán đám mây NIST SP 800-145: 5 đặc tính, 3 mô hình dịch vụ (IaaS, PaaS, SaaS), 4 mô hình triển khai.","Khung Well-Architected với 6 trụ cột: vận hành xuất sắc, bảo mật, độ tin cậy, hiệu năng, tối ưu chi phí, bền vững.","Mô hình trách nhiệm chia sẻ giữa nhà cung cấp đám mây và khách hàng.","Chiến lược phục hồi thảm họa: sao lưu - khôi phục, pilot light, warm standby, đa vùng chủ động - chủ động.","ISO/IEC 27017 (kiểm soát bảo mật cho dịch vụ đám mây) và ISO/IEC 27018 (bảo vệ dữ liệu cá nhân trên đám mây công cộng).","Quy định hiện hành của Việt Nam về bảo vệ dữ liệu cá nhân và chuyển dữ liệu ra nước ngoài."],en:["NIST SP 800-145 cloud definition: 5 characteristics, 3 service models (IaaS, PaaS, SaaS), 4 deployment models.","The Well-Architected framework with 6 pillars: operational excellence, security, reliability, performance, cost optimization, sustainability.","The shared responsibility model between the cloud provider and the customer.","Disaster recovery strategies: backup and restore, pilot light, warm standby, multi-site active-active.","ISO/IEC 27017 (security controls for cloud services) and ISO/IEC 27018 (protection of personal data in public clouds).","Current Vietnamese rules on personal data protection and cross-border data transfer."]},tools:["Terraform (IaC)","CLI & bảng điều khiển đám mây","Công cụ ước tính chi phí đám mây","Kubernetes","Công cụ vẽ sơ đồ kiến trúc","Công cụ thử tải (k6/JMeter)"],kpis:{vi:["Mức đạt SLO sẵn sàng của hệ thống sau khi đưa vào vận hành.","Kết quả diễn tập DR đạt RPO, RTO đã cam kết.","Chi phí đám mây hằng tháng so với ngân sách và chi phí trên mỗi giao dịch.","Số phát hiện bảo mật mức cao trong rà soát kiến trúc (mục tiêu bằng 0)."],en:["Availability SLO attainment after go-live.","DR drill results meeting the committed RPO and RTO.","Monthly cloud spend against budget and cost per transaction.","High-severity security findings in architecture reviews (target zero)."]},day:[{time:"08:30",vi:"Xem bảng chi phí và cảnh báo bảo mật đám mây, đánh dấu tài nguyên bất thường.",en:"Check the cloud cost board and security alerts and flag unusual resources."},{time:"10:00",vi:"Họp đội sản phẩm thu thập yêu cầu tải, RPO, RTO cho dịch vụ mới.",en:"Meet the product team to gather load, RPO and RTO needs for a new service."},{time:"13:30",vi:"Vẽ kiến trúc đa AZ và viết ADR so sánh hai phương án cơ sở dữ liệu.",en:"Draw a multi-AZ architecture and write an ADR comparing two database options."},{time:"15:30",vi:"Rà soát mã Terraform của đội hạ tầng và kết quả thử tải mới nhất.",en:"Review the infrastructure team's Terraform code and the latest load test."},{time:"17:00",vi:"Trình bày đánh đổi chi phí và độ tin cậy với hội đồng kiến trúc.",en:"Present cost versus reliability trade-offs to the architecture board."}],mistakes:{vi:["Tính số máy theo tải đỉnh nhưng quên kịch bản mất một vùng sẵn sàng.","Dùng cơ sở dữ liệu một AZ, sao lưu hằng ngày cho hệ thống yêu cầu RPO bằng 0.","Mở cổng cơ sở dữ liệu ra Internet hoặc sao chép dữ liệu thật sang môi trường không kiểm soát."],en:["Sizing for peak load but forgetting the loss of an availability zone.","Using a single-AZ database with daily backups for a system that needs RPO zero.","Exposing database ports to the Internet or copying real data to uncontrolled environments."]},career:[{vi:"Kỹ sư hạ tầng đám mây",en:"Cloud infrastructure engineer"},{vi:"Kiến trúc sư giải pháp đám mây",en:"Cloud solutions architect"},{vi:"Kiến trúc sư đám mây cao cấp / Trưởng nhóm nền tảng",en:"Principal cloud architect / Platform lead"},{vi:"Kiến trúc sư doanh nghiệp / Giám đốc công nghệ hạ tầng",en:"Enterprise architect / Head of infrastructure technology"}],glossary:[{term:"Availability Zone",vi:"Vùng sẵn sàng: một hoặc nhiều trung tâm dữ liệu độc lập về điện và mạng trong cùng một khu vực.",en:"One or more data centers with independent power and networking inside the same region."},{term:"RPO",vi:"Lượng dữ liệu tối đa có thể mất, đo bằng thời gian, khi xảy ra sự cố.",en:"Maximum acceptable data loss, measured in time, when an incident occurs."},{term:"RTO",vi:"Thời gian tối đa được phép để khôi phục dịch vụ sau sự cố.",en:"Maximum time allowed to restore a service after an incident."},{term:"IaC",vi:"Hạ tầng dưới dạng mã: mô tả tài nguyên bằng tệp cấu hình có quản lý phiên bản và rà soát.",en:"Infrastructure as code: resources described in versioned, reviewed configuration files."},{term:"Auto Scaling",vi:"Tự động tăng giảm số máy theo chỉ số tải trong giới hạn tối thiểu và tối đa.",en:"Automatically adding or removing servers based on load metrics within minimum and maximum limits."}],quiz:[{q:{vi:"Hệ thống yêu cầu RPO = 0 trong một region và chịu lỗi một AZ. Kiểu triển khai cơ sở dữ liệu nào phù hợp?",en:"A system needs RPO = 0 within one region and must survive one AZ loss. Which database deployment fits?"},options:{vi:["Một AZ, sao lưu hằng ngày","Đa AZ với bản dự phòng đồng bộ","Bản sao bất đồng bộ ở region khác","Xuất dữ liệu ra tệp mỗi giờ"],en:["Single AZ with daily backup","Multi-AZ with a synchronous standby","Asynchronous replica in another region","Hourly export to files"]},answer:1,explain:{vi:"Sao chép đồng bộ sang AZ khác giữ RPO bằng 0 và dữ liệu vẫn nằm trong cùng region.",en:"Synchronous replication to another AZ keeps RPO at zero while data stays in the same region."}},{q:{vi:"Đỉnh tải 3000 yêu cầu/giây, mỗi máy xử lý 500 yêu cầu/giây ở CPU mục tiêu, cụm trên 3 AZ phải chịu mất 1 AZ. Số máy tối thiểu là bao nhiêu?",en:"Peak is 3000 req/s, each server handles 500 req/s at target CPU, and a 3-AZ fleet must survive one AZ loss. What is the minimum?"},options:{vi:["6 máy","7 máy","8 máy","9 máy"],en:["6 servers","7 servers","8 servers","9 servers"]},answer:3,explain:{vi:"N = 3000 / 500 = 6; mỗi AZ = làm tròn lên (6 / 2) = 3; tổng = 3 x 3 = 9 máy.",en:"N = 3000 / 500 = 6; per AZ = round up (6 / 2) = 3; total = 3 x 3 = 9 servers."}},{q:{vi:"Theo mô hình trách nhiệm chia sẻ, ai cấu hình quyền IAM truy cập dữ liệu của khách hàng?",en:"Under the shared responsibility model, who configures IAM access to the customer's data?"},options:{vi:["Khách hàng sử dụng đám mây","Nhà cung cấp đám mây","Nhà mạng Internet","Không ai, mặc định đã an toàn"],en:["The cloud customer","The cloud provider","The Internet carrier","Nobody, defaults are secure"]},answer:0,explain:{vi:"Nhà cung cấp bảo vệ hạ tầng; khách hàng chịu trách nhiệm cấu hình danh tính, quyền và dữ liệu của mình.",en:"The provider secures the infrastructure; the customer is responsible for identities, permissions and its own data."}},{q:{vi:"Giám đốc yêu cầu sao chép dữ liệu khách hàng thật sang tài khoản cá nhân ở nước ngoài để demo. Bạn làm gì?",en:"A director asks you to copy real customer data to a personal overseas account for a demo. What do you do?"},options:{vi:["Làm rồi xóa sau buổi demo","Chỉ mở cổng cơ sở dữ liệu trong 1 giờ","Từ chối, báo cáo và đề xuất demo bằng dữ liệu giả lập trong môi trường được phép","Gửi tệp sao lưu qua thư điện tử cho đối tác"],en:["Do it and delete after the demo","Open the database port for just 1 hour","Refuse, escalate and propose a synthetic-data demo in an approved environment","Email the backup file to the partner"]},answer:2,explain:{vi:"Dữ liệu cá nhân thật không được chuyển ra môi trường không kiểm soát hay ra nước ngoài khi chưa đủ căn cứ pháp lý và phê duyệt.",en:"Real personal data must not move to uncontrolled or overseas environments without a legal basis and approval."}}],tools_en:["Terraform (IaC)","Cloud CLI & console","Cloud cost estimation tools","Kubernetes","Architecture diagramming tools","Load testing tools (k6/JMeter)"]}}})})(window.KKR);
